-- ============================================================================
-- Data Comparison 全功能演练表(Hive)· dc_test_sales_a / dc_test_sales_b
-- 一对表覆盖侧栏全部功能,预置差异与预期结果:
--   * 行数: A 40 / B 39(B 缺 id=15,33;B 多 id=99)→ 阈值 5% 不过、10% 过
--   * 主键列: id(样本/键控 diff、分块校验用)
--   * 字段映射: cust_name:customer_name(B 侧重命名,结构对比会标出)
--   * 修改行: id=7 amount 700→770;id=21 status paid→refund
--   * 容差: id=30 amount 3000.10 vs 3000.1000001 → 聚合/分块判等(归一化)
--   * WHERE: dt = '2024-06-02' 只剩 10 vs 9(B 缺 id=15)
--   * 分区比对: 分区列 dt(2024-06-01..04;06-02 差 1,06-04 差 0[缺33补99])
--   * 增量对比: 水位线列 update_time,水位 '2024-06-05 00:00:00' → 5 vs 6 行
--   * 数据倾斜: 倾斜列 region(两侧 north 均约 70%,top1 高集中)
--   * 分层采样: 分层列 channel(app/web/store)
--   * 质量规则: email:not_null>95(B 侧 id=12 为 NULL,≈97.4% 临界)、
--               amount:range:0-2000(B 侧 id=99 =5000 违规)
--   * 脱敏: phone / email 自动识别
--   * 自定义聚合: total=SUM(amount)(A≈82010 vs B≈86380,差异)
--                 regions=COUNT(DISTINCT region)(=4,一致)
--   * 校验和/分块校验: 校验列留空(全共同列)即可;分块主键 id
-- 清理: DROP TABLE IF EXISTS dc_test_sales_a; DROP TABLE IF EXISTS dc_test_sales_b;
-- ============================================================================

DROP TABLE IF EXISTS dc_test_sales_a;
CREATE TABLE dc_test_sales_a (
  id INT, order_no STRING, dt STRING, region STRING, channel STRING,
  cust_name STRING, amount DOUBLE, status STRING, phone STRING,
  email STRING, update_time STRING
);

DROP TABLE IF EXISTS dc_test_sales_b;
CREATE TABLE dc_test_sales_b (
  id INT, order_no STRING, dt STRING, region STRING, channel STRING,
  customer_name STRING, amount DOUBLE, status STRING, phone STRING,
  email STRING, update_time STRING
);
